Find the area bounded by $x=2y^2$, the $y$-axis and the lines $y=1$ and $y=2$.
[tikz]
\begin{tikzpicture}[x=0.55cm,y=1.25cm,every node/.style={font=\fontsize{10}{12}\selectfont,text=black}]
\definecolor{regionfill}{HTML}{D4E8FF}
\fill[regionfill] (0,1)--plot[domain=1:2,variable=\t,samples=60] ({2*\t*\t},{\t})--(0,2)--cycle;
\draw[black,->] (-0.5,0)--(9.5,0) node[right] {$x$};
\draw[black,->] (0,-0.3)--(0,2.7) node[above] {$y$};
\draw[black,thick,->] plot[domain=0:2.15,variable=\t,samples=60] ({2*\t*\t},{\t});
\draw[black] (0,1)--(2,1) (0,2)--(8,2);
\path (0,1) node[left] {$1$} (0,2) node[left] {$2$};
\end{tikzpicture}
[/tikz]

